import csv, hashlib, json, os, pathlib, platform, subprocess, sys, datetime
root=pathlib.Path.cwd(); out=root/'artifacts'; (out/'tmp').mkdir()
env=dict(os.environ, TMPDIR=str(out/'tmp'), PYTHONDONTWRITEBYTECODE='1')
files=['requirements.md','export.py','test_export.py','fixtures/pages.json','fixtures/expected_records.json','fixtures/empty_pages.json']
def hashes(): return {p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in files}
before=hashes()
manifest={'cwd':str(root),'python':sys.executable,'version':sys.version,'platform':platform.platform(),'started':datetime.datetime.now(datetime.timezone.utc).isoformat(),'before':before}
(out/'identity.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
records=[]
def run(name,args):
    p=subprocess.run(args,cwd=root,env=env,text=True,capture_output=True,timeout=35)
    rec={'name':name,'argv':args,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr,'completed':True}
    records.append(rec); (out/(name+'.process.json')).write_text(json.dumps(rec,ensure_ascii=False,indent=2)); return p
suite=run('native-tests',[sys.executable,'-B','-m','unittest','-v','test_export'])
print(suite.stderr)
expected=json.loads((root/'fixtures/expected_records.json').read_text())
def export(name,source='fixtures/pages.json',output=None,fault=False):
    args=[sys.executable,'-B','export.py','--source',str(source),'--output',str(output or out/(name+'.csv'))]
    if fault: args+=['--fault','omit-final-page']
    return run(name,args)
def read(path):
    with path.open(encoding='utf-8',newline='') as f:
        reader=csv.DictReader(f,strict=True); rows=list(reader); return reader.fieldnames,rows
checks={}
for name,fault in [('healthy',False),('fault',True)]:
    p=export(name,fault=fault); columns,rows=read(out/(name+'.csv'))
    checks[name]={'exit_code':p.returncode,'columns':columns,'count':len(rows),'ids':[r['id'] for r in rows],'exact_expected_match':rows==expected,'business_verdict':'PASS' if p.returncode==0 and columns==['id','title','notes'] and rows==expected else 'FAIL','rows':rows}
original=b'existing user data\\x00\\xff'; target=out/'existing.csv'; target.write_bytes(original); (out/'existing-before.bin').write_bytes(original)
p=export('existing-protection',output=target)
checks['existing-protection']={'exit_code':p.returncode,'unchanged':target.read_bytes()==original,'error_visible':bool(p.stderr)}
bad=out/'invalid.json'; bad.write_text('{\"pages\":')
p=export('invalid-existing-protection',source=bad,output=target)
checks['invalid-existing-protection']={'exit_code':p.returncode,'unchanged':target.read_bytes()==original,'error_visible':bool(p.stderr)}
p=export('invalid-new',source=bad)
checks['invalid-new']={'exit_code':p.returncode,'final_absent':not (out/'invalid-new.csv').exists(),'error_visible':bool(p.stderr)}
# Explicit local filesystem-failure simulation; the native CLI entrypoint is executed under an os.link stub.
code=\"import os,runpy,sys; from unittest.mock import patch; sys.argv=['export.py','--source','fixtures/pages.json','--output',sys.argv[1]]; ctx=patch('os.link',side_effect=OSError('simulated exclusive publication unavailable')); ctx.start(); runpy.run_path('export.py',run_name='__main__')\"
p=run('exclusive-publication-unavailable',[sys.executable,'-B','-c',code,str(out/'unpublishable.csv')])
checks['exclusive-publication-unavailable']={'scope':'explicit simulated os.link failure','exit_code':p.returncode,'final_absent':not (out/'unpublishable.csv').exists(),'error_visible':bool(p.stderr)}
checks['native-suite']={'exit_code':suite.returncode,'log':'native-tests.process.json'}
checks['integrity']={'protected_files_unchanged':before==hashes(),'after':hashes()}
checks['execution']={'all_child_processes_terminated':all(r['completed'] for r in records),'export_temporary_residuals':[str(p.relative_to(out)) for p in out.rglob('.export-*.tmp')],'retention':'until project owner removes; no active child writers'}
(out/'observations.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2))
print(json.dumps(checks,ensure_ascii=False,indent=2))
PY"

